262	fn did_key_for_scalar(scalar: &[u8; 32]) -> Result<String, DisasterRecoveryError> {
263	    use p256::elliptic_curve::sec1::ToEncodedPoint;
264	    let secret = p256::SecretKey::from_bytes(scalar.as_slice().into()).map_err(|e| {
265	        DisasterRecoveryError::SigningFailed {
266	            message: format!("stored recovery signing key is not a valid P-256 scalar: {e}"),
267	        }
268	    })?;
269	    let compressed = secret.public_key().to_encoded_point(true);
270	    let mut multikey = Vec::with_capacity(2 + compressed.as_bytes().len());
271	    multikey.extend_from_slice(&[0x80, 0x24]);
272	    multikey.extend_from_slice(compressed.as_bytes());
273	    Ok(format!(
274	        "did:key:{}",
275	        multibase::encode(multibase::Base::Base58Btc, &multikey)
276	    ))
277	}
