279	/// Signing closure over the stored recovery signing key scalar: deterministic (RFC
280	/// 6979) P-256 ECDSA, low-S normalized, raw 64-byte r‖s — the contract every crypto
281	/// builder and the service-auth JWT verifier expect.
282	fn recovery_sign_closure(
283	    scalar: zeroize::Zeroizing<[u8; 32]>,
284	) -> impl FnOnce(&[u8]) -> Result<Vec<u8>, crypto::CryptoError> {
285	    move |data: &[u8]| {
286	        use p256::ecdsa::signature::Signer;
287	        let sk = p256::ecdsa::SigningKey::from_bytes(scalar.as_slice().into())
288	            .map_err(|e| crypto::CryptoError::PlcOperation(format!("invalid signing key: {e}")))?;
289	        let sig: p256::ecdsa::Signature = sk.sign(data);
290	        let sig = sig.normalize_s().unwrap_or(sig);
291	        Ok(sig.to_bytes().to_vec())
292	    }
293	}
